COMMENT ON TABLE public."ComplexStatsCache" IS 'One row per (group_id, temporal_unit, time_period), for all species combined: the lifetime-relative demographics_stats_result metrics (new_adult_bird_count and the four returning_age_* columns), which read a bird''s whole unwindowed history and so must be fully replaced on refresh rather than narrowed to affected dates. Per-species rows live in "ComplexStatsCacheBySpecies"; period-local metrics live in "SimpleStatsCache".';
COMMENT ON COLUMN public."ComplexStatsCache".time_period IS 'The cell''s period, as the first date in it. NOT NULL: the all-time grain uses the sentinel date ''0001-01-01'' rather than a NULL, so a single plain UNIQUE constraint covers every grain and a native supabase-js .upsert() can name it as a conflict target.';
ALTER TABLE public."ComplexStatsCache" ADD CONSTRAINT complex_stats_cache_group_grain_period_key UNIQUE (group_id, temporal_unit, time_period);
CREATE TABLE public."ComplexStatsCacheBySpecies" (id bigint DEFAULT nextval('public."ComplexStatsCacheBySpecies_id_seq"'::regclass) NOT NULL, group_id bigint NOT NULL, temporal_unit text NOT NULL, time_period date NOT NULL, species_id bigint NOT NULL, new_adult_bird_count bigint NOT NULL, returning_age_1_bird_count bigint NOT NULL, returning_age_2_bird_count bigint NOT NULL, returning_age_3_plus_bird_count bigint NOT NULL, returning_new_unknown_age_bird_count bigint NOT NULL);
ALTER SEQUENCE public."ComplexStatsCacheBySpecies_id_seq" OWNED BY public."ComplexStatsCacheBySpecies".id;
GRANT UPDATE ON SEQUENCE public."ComplexStatsCacheBySpecies_id_seq" TO anon;
GRANT UPDATE ON SEQUENCE public."ComplexStatsCacheBySpecies_id_seq" TO authenticated;
GRANT UPDATE ON SEQUENCE public."ComplexStatsCacheBySpecies_id_seq" TO service_role;
COMMENT ON TABLE public."ComplexStatsCacheBySpecies" IS 'One row per (group_id, temporal_unit, time_period, species_id): the lifetime-relative demographics_stats_result metrics (new_adult_bird_count and the four returning_age_* columns), per species. All-species-combined rows live in "ComplexStatsCache"; period-local metrics live in "SimpleStatsCacheBySpecies".';
COMMENT ON COLUMN public."ComplexStatsCacheBySpecies".time_period IS 'The cell''s period, as the first date in it. NOT NULL: the all-time grain uses the sentinel date ''0001-01-01'' rather than a NULL, so a single plain UNIQUE constraint covers every grain and a native supabase-js .upsert() can name it as a conflict target.';
COMMENT ON COLUMN public."ComplexStatsCacheBySpecies".species_id IS 'NOT NULL — unlike this table''s predecessor, there is no "all species combined" sentinel or NULL here. Those rows live in the "ComplexStatsCache" table instead.';
ALTER TABLE public."ComplexStatsCacheBySpecies" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."ComplexStatsCacheBySpecies" ADD CONSTRAINT "ComplexStatsCacheBySpecies_pkey" PRIMARY KEY (id);
